uint8_t nx_ucd_bidi_bracket(uint32_t scalar, uint32_t *paired) {
    size_t low = 0, high = sizeof(nx_ucd_brackets) / sizeof(nx_ucd_brackets[0]);
    while (low < high) {
        size_t middle = low + (high - low) / 2u;
        if (scalar < nx_ucd_brackets[middle].scalar) high = middle;
        else if (scalar > nx_ucd_brackets[middle].scalar) low = middle + 1u;
        else {
            if (paired) *paired = nx_ucd_brackets[middle].paired;
            return nx_ucd_brackets[middle].kind;
        }
    }
    return 0;
}
